$st=$pdo->prepare('SELECT id_keluarga FROM keluarga WHERE id_user=? LIMIT 1'); $st->execute([$_SESSION['user_id']]);
$idKeluarga=(int)($st->fetchColumn() ?: 0);
$st=$pdo->prepare("SELECT l.*, TIMESTAMPDIFF(YEAR,l.tanggal_lahir,CURDATE()) usia,p.nama_posyandu FROM lansia l LEFT JOIN posyandu p ON p.id_posyandu=l.id_posyandu WHERE l.id_keluarga=? AND l.status_lansia='aktif' ORDER BY l.nama_lengkap");
$st->execute([$idKeluarga]); $daftarLansia=$st->fetchAll();
$idLansia=array_map('intval',array_column($daftarLansia,'id_lansia'));
function h($v): string { return htmlspecialchars((string)($v??'-'),ENT_QUOTES,'UTF-8'); }
function tgl_id($v): string { if(!$v)return '-'; $b=[1=>'Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];$t=strtotime($v);return date('d',$t).' '.$b[(int)date('n',$t)].' '.date('Y',$t); }
function jam_id($v): string { return $v?date('H:i',strtotime($v)):'-'; }
function warna_status($s): string { if(in_array($s,['Aman / Sehat','Normal','aktif','terjadwal','Tidak'],true))return 'ok';if(in_array($s,['Perlu Perhatian','Pra-hipertensi','Kelebihan BB','Kurus','Hipotensi','Rendah'],true))return 'warn';if(in_array($s,['Risiko Tinggi','Hipertensi 1','Hipertensi 2','Tinggi','Obesitas','Ya'],true))return 'danger';return 'muted'; }
function get_riwayat(PDO $pdo,array $ids): array { if(!$ids)return []; $q=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT rk.*,l.nama_lengkap nama_lansia,l.id_lansia FROM riwayat_kesehatan rk JOIN lansia l ON l.id_lansia=rk.id_lansia WHERE l.id_lansia IN ($q) ORDER BY rk.tanggal_pemeriksaan DESC,rk.waktu_pemeriksaan DESC,rk.id_riwayat DESC");$s->execute($ids);return $s->fetchAll(); }
